package ma.translogix.model;

import java.time.LocalDateTime;

/**
 * One road incident reported by the dispatcher for a mission.
 * The reference INC-xxxx is generated by IncidentService.
 */
public class Incident {
    private Long id;
    private String reference;
    private Long missionId;
    private TypeIncident type;
    private GraviteIncident gravite;
    private String description;
    private String localisation;
    private LocalDateTime dateSignalement;
    private StatutIncident statut = StatutIncident.OUVERT;

    public Incident() {
    }

    public Incident(Long id, String reference, Long missionId, TypeIncident type, GraviteIncident gravite,
                    String description, String localisation, LocalDateTime dateSignalement, StatutIncident statut) {
        this.id = id;
        this.reference = reference;
        this.missionId = missionId;
        this.type = type;
        this.gravite = gravite;
        this.description = description;
        this.localisation = localisation;
        this.dateSignalement = dateSignalement;
        this.statut = statut;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getReference() { return reference; }
    public void setReference(String reference) { this.reference = reference; }

    public Long getMissionId() { return missionId; }
    public void setMissionId(Long missionId) { this.missionId = missionId; }

    public TypeIncident getType() { return type; }
    public void setType(TypeIncident type) { this.type = type; }

    public GraviteIncident getGravite() { return gravite; }
    public void setGravite(GraviteIncident gravite) { this.gravite = gravite; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getLocalisation() { return localisation; }
    public void setLocalisation(String localisation) { this.localisation = localisation; }

    public LocalDateTime getDateSignalement() { return dateSignalement; }
    public void setDateSignalement(LocalDateTime dateSignalement) { this.dateSignalement = dateSignalement; }

    public StatutIncident getStatut() { return statut; }
    public void setStatut(StatutIncident statut) { this.statut = statut; }
}
